'use client';

import React, { useState } from 'react';
import { getMediaUrl } from '@/lib/media';
import { SUTURA_LOGO_URL } from '@/lib/brandedExport';

/**
 * Themed frame for printable statements and reports (also what "Save as PDF" saves):
 * the shop's logo (SUTURA's when it has none), a taupe rule, SUTURA-coloured tables
 * and a "Generated by SUTURA" footer with page numbers.
 *
 * Printing note: globals.css hides everything except #receipt-print-area when
 * printing, so the document must live inside that id or it prints blank.
 */
export default function PrintDocument({ org, logoPath, title, subtitle, children }: Readonly<{
  org: string;
  /** The shop's stored logo path; null/empty uses the SUTURA logo. */
  logoPath?: string | null;
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}>) {
  const [logoFailed, setLogoFailed] = useState(false);
  const logo = logoPath && !logoFailed ? getMediaUrl(logoPath) : SUTURA_LOGO_URL;

  return (
    <>
      <style>{`
        @page {
          size: A4;
          margin: 14mm 12mm 16mm;
          @bottom-left { content: "Generated by SUTURA · suturaofficial.tech"; font: 8pt system-ui, sans-serif; color: #827A73; }
          @bottom-right { content: "Page " counter(page) " of " counter(pages); font: 8pt system-ui, sans-serif; color: #827A73; }
        }
        #receipt-print-area { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
        @media print {
          /* The app's beige canvas would otherwise show below the document on the last page. */
          html, body { background: #fff !important; }
          #receipt-print-area { padding: 0 !important; }
          /* Each page's footer already says "Generated by SUTURA" with page numbers. */
          .pd-end { display: none !important; }
        }
        .pd-table { width: 100%; border-collapse: collapse; font-size: 11px; }
        .pd-table thead { display: table-header-group; }
        .pd-table th { background: #9A8073; color: #fff; font-weight: 700; text-align: left; padding: 6px 8px; }
        .pd-table td { padding: 5px 8px; border-bottom: 1px solid #EBE6E0; color: #2D2A26; vertical-align: top; }
        .pd-table tbody tr:nth-child(even) td { background: #FAF6F3; }
        .pd-table tr { break-inside: avoid; }
        .pd-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
        .pd-table tfoot td { border-top: 2px solid #9A8073; border-bottom: 0; font-weight: 700; font-size: 12px; background: #fff; }
      `}</style>

      <div className="no-print sticky top-0 z-10 flex justify-end gap-2 border-b border-[#EBE6E0] bg-white/95 px-6 py-3 backdrop-blur">
        <button type="button" onClick={() => window.history.back()} className="h-10 rounded-lg border border-[#D9D1C8] px-4 text-sm font-medium text-[#2D2A26] hover:bg-[#FAF6F3] cursor-pointer">Back</button>
        <button type="button" onClick={() => window.print()} className="h-10 rounded-lg bg-[#9A8073] px-4 text-sm font-semibold text-white hover:bg-[#91756A] cursor-pointer">Print / Save as PDF</button>
      </div>

      <div id="receipt-print-area" className="mx-auto max-w-[1000px] bg-white p-8 text-[#2D2A26]">
        <header className="flex items-center gap-4 border-b-2 border-[#9A8073] pb-4">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={logo}
            alt=""
            onError={() => setLogoFailed(true)}
            className="h-14 w-auto max-w-[180px] shrink-0 object-contain"
          />
          <div className="min-w-0">
            <p className="text-xl font-bold leading-tight text-[#2D2A26]">{org}</p>
            <h1 className="text-sm font-bold uppercase tracking-wider text-[#6B4E3E]">{title}</h1>
            {subtitle && <p className="text-xs text-[#827A73]">{subtitle}</p>}
          </div>
        </header>

        <div className="mt-5">{children}</div>

        <footer className="pd-end mt-8 flex items-center gap-2 border-t border-[#EBE6E0] pt-3 text-[10px] text-[#827A73]">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src="/images/logo-icon.svg" alt="" className="h-4 w-4" />
          Generated by SUTURA · suturaofficial.tech · {new Date().toLocaleString('en-PH', { timeZone: 'Asia/Manila' })}
        </footer>
      </div>
    </>
  );
}

/** Big-number strip under the header (records, totals). */
export function PrintSummary({ items }: Readonly<{ items: [string, string][] }>) {
  return (
    <dl className="mb-5 grid grid-cols-2 gap-x-8 gap-y-3 sm:grid-cols-4">
      {items.map(([k, v]) => (
        <div key={k}>
          <dt className="text-[10px] font-bold uppercase tracking-wider text-[#827A73]">{k}</dt>
          <dd className="text-lg font-bold tabular-nums text-[#2D2A26]">{v}</dd>
        </div>
      ))}
    </dl>
  );
}
